-- UPDATE SEASON COUNTS (adjust arc_id references if needed)
-- ═════════════════════════════════════════════════════════════
-- Update canon_order to ensure proper sorting
UPDATE content_entries SET canon_order = episode_number WHERE type = 'episode';
UPDATE content_entries SET canon_order = 1000 + movie_number WHERE type = 'movie';
UPDATE content_entries SET canon_order = 2000 + (EXTRACT(YEAR FROM air_date::date) - 2000) * 100 WHERE type IN ('special', 'ova');
